arguments.command:
mkdir -p tests/CheckoutPricing.IntegrationTests/Checkout
cat > src/CheckoutPricing.Domain/CustomerTier.cs <<'E'
namespace CheckoutPricing.Domain;

public enum CustomerTier
{
    Standard,
    Gold
}
E
cat > src/CheckoutPricing.Application/Checkout.cs <<'E'
using CheckoutPricing.Domain;

namespace CheckoutPricing.Application;

public sealed class Checkout
{
    public decimal CalculatePayableTotal(CustomerTier tier, decimal orderSubtotal) => orderSubtotal;
}
E
cat > tests/CheckoutPricing.IntegrationTests/Checkout/LoyaltyDiscountTests.cs <<'E'
using CheckoutPricing.Domain;

namespace CheckoutPricing.IntegrationTests.Checkout;

public sealed class LoyaltyDiscountTests
{
    [Fact]
    public void Gold_customer_with_100_00_subtotal_pays_95_00()
    {
        var checkout = new CheckoutPricing.Application.Checkout();

        var payable = checkout.CalculatePayableTotal(CustomerTier.Gold, 100.00m);

        Assert.Equal(95.00m, payable);
    }
}
E
dotnet test tests/CheckoutPricing.IntegrationTests 2>&1 | tail -25

